{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement. ... It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used. There is a disconnect between evaluating the factors that may shape sustainability and the outcomes approaches employed to measure sustainability.",
      "reason": "The text explicitly describes the limited evidence regarding sustainability evaluation and identifies specific uncertainties, such as which approaches are effective and the disconnect between evaluating factors versus outcomes."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated. A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The authors explain the importance of the review by stating that evaluation is necessary for effectiveness and that this review fills a gap by focusing on evaluation, differentiating it from other syntheses."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "Our synthesis indicated that there is a breadth of theoretical approaches and constructs that were considered for the evaluation of the sustainability of EBIs in healthcare that were consistent with other recent synthesis work [6-10]. ... In a review by Lennox et al., they indicated that only 21% of studies reported any information on sustainability outcomes [6].",
      "reason": "The authors acknowledge existing reviews (e.g., Lennox et al.) and explain how their review provides further insight (e.g., reporting on timing, methods, measures, and outcomes) beyond those existing works."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review identifying approaches to evaluate sustainability, not a review of the effects of a specific intervention; therefore, a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not a primary study of a complex intervention requiring a logic model; it is a review of evaluation approaches."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review explicitly states its objectives in the 'Aim' section, clearly defining the purpose of the integrative review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review aiming to identify and synthesize existing approaches to evaluate sustainability, not a review of intervention effects comparing specific interventions. Therefore, PICO is not applicable."
    }
  ],
  "confidence": 100
}

{
